export const expansionWalkthroughs={};
const cell=(label,value,detail='')=>({label,value,detail});
const F=(title,code,why,watch,cells,focus=[],extra={})=>({title,code,why,watch,cells,focus,links:[],...extra});
const flow=(id,assumption,frames)=>expansionWalkthroughs[id]={kind:'flow',assumption,frames};
flow('linux-fork','单线程，fork成功；PID 100/101为示意。x是普通私有变量，父子执行先后未指定。',[
 F('只有父进程','int x=7;','程序开始时只有父进程持有这一份变量。',[['进程总数','1']],[cell('父 PID100','x = 7','即将调用fork')],[0]),
 F('fork产生两条执行路径','pid_t pid=fork();','父获得子PID，子获得0；二者都从这一行之后继续，不重新执行main开头。',[['父返回值','101'],['子返回值','0'],['进程总数','2']],[cell('父 PID100','pid = 101','x = 7'),cell('子 PID101','pid = 0','x = 7')],[0,1]),
 F('仅子分支修改x','if(pid==0) x=9;','只在子分支成立。写时复制使物理实现高效，但普通私有内存逻辑上仍独立。',[['父x','7'],['子x','9']],[cell('父 PID100','x = 7','子写入不改变它'),cell('子 PID101','x = 9','自己的私有变量')],[1]),
 F('父等待子结束','// 父：waitpid(pid,&status,0)','waitpid建立回收关系；它不会把子变量x的值复制回来。',[['通信是否发生','没有通过x通信']],[cell('父 PID100','收集退出状态','x仍为7'),cell('子 PID101','退出并被回收','x不会自动传回')],[0])
]);
flow('linux-exec','单线程示意，父PID100、子PID101；演示exec成功路径以及单独的失败分支。',[
 F('先由fork创建子进程','pid=fork();','同一程序的两份运行实例；子还未换程序。',[['进程数','2']],[cell('父 PID100','原程序','负责等待'),cell('子 PID101','原程序','准备execv')],[1]),
 F('子组织参数','char *args[]={"app","-v",NULL};','args数组存放字符串指针；NULL结束的是参数数组，各字符串另有自己的结束字符。',[['argv[0]','app'],['argv[1]','-v'],['argv[2]','NULL']],[cell('参数0','app','程序名'),cell('参数1','-v','普通参数'),cell('结束标记','NULL','不是字符串')],[2]),
 F('成功：换程序，PID保留','execv("/path/app",args);','新程序接管同一个子进程，旧代码下一行不执行；并没有第三个进程。',[['子PID','仍为101'],['旧exec是否返回','否']],[cell('父 PID100','原程序','继续等待'),cell('子 PID101','新程序 app','代码/数据已替换')],[1]),
 F('另一条路径：执行失败','execv(...); _exit(127);','失败才返回旧程序，必须收住子分支；127是此示例选用的退出约定。',[['exec返回','-1'],['进程数','不会因exec增加']],[cell('父 PID100','waitpid','收集状态'),cell('子 PID101','旧程序错误路径','exec失败后退出')],[1])
]);
flow('linux-devicetree','硬件描述到驱动工作的简化链路；真实枚举规则由总线及binding决定。',[
 F('人编辑源码描述','board.dts + 公共 .dtsi','把硬件位置、连接和资源写成树；描述本身不读写设备寄存器。',[['内容','节点、属性与引用']],[cell('源码','DTS / DTSI','可阅读的硬件描述'),cell('驱动','内核代码','操作设备的实现')],[0]),
 F('编译并选择启动用的树','DTC → board.dtb','DTB是二进制树；必须确认bootloader实际加载的是这份文件。',[['输入','设备树源码'],['输出','DTB']],[cell('DTC','编译工具','检查与编码'),cell('DTB','二进制树','供启动流程使用')],[1]),
 F('内核读取与枚举','compatible / reg / status','内核根据树和总线规则建立相应设备，资源按父节点和binding解释。',[['reg','先看父cell数'],['status','启用条件之一']],[cell('内核','读取描述','不等于所有设备已就绪'),cell('设备对象','等待匹配','具备资源描述')],[1]),
 F('匹配并执行probe','match → probe → 子系统接口','匹配后尝试初始化；时钟或依赖缺失仍可能失败/延后。',[['排查顺序','实际DTB → 匹配 → probe日志']],[cell('驱动匹配','对应总线规则','例如compatible匹配'),cell('probe','初始化资源','检查返回值'),cell('用户接口','按子系统提供','不保证都是/dev')],[1])
]);
flow('r-priority-basics','单核FreeRTOS，抢占开启；A=3、B=2、C=1。每帧表示所述事件后的状态。',[
 F('三者就绪，A运行','// Ready: A,B,C','调度器从就绪集合选最高任务优先级3。',[['CPU','A'],['Ready集合（含运行者）','A,B,C']],[cell('A / 3','运行','最高就绪'),cell('B / 2','就绪','等待CPU'),cell('C / 1','就绪','等待CPU')],[0]),
 F('A等待队列，B运行','xQueueReceive(q,&data,portMAX_DELAY);','假设队列空且等待有效，A阻塞；高优先级不再让它占CPU。',[['CPU','B'],['Ready集合','B,C']],[cell('A / 3','阻塞','等队列'),cell('B / 2','运行','当前最高就绪'),cell('C / 1','就绪','等待CPU')],[1]),
 F('B延时，C运行','vTaskDelay(10);','B在延时期间阻塞，C成为剩余最高就绪。',[['CPU','C'],['Ready集合','C']],[cell('A / 3','阻塞','等队列'),cell('B / 2','阻塞','等时间'),cell('C / 1','运行','有机会工作')],[2]),
 F('ISR唤醒A，退出中断后切换','xQueueSendFromISR(...); portYIELD_FROM_ISR(woke);','中断优先级合法且发送成功并请求切换，A恢复就绪后抢占C。',[['CPU（退出ISR后）','A'],['Ready集合','A,C']],[cell('A / 3','运行','收到数据'),cell('B / 2','阻塞','延时未到'),cell('C / 1','就绪','被抢占')],[0])
]);
flow('r-priority-inversion','单核、单把Mutex，H=3/M=2/L=1；先展示无继承干扰，再展示继承机制。',[
 F('L先获得锁','L: take(mutex);','H此时还未就绪，所以L能运行并进入临界区。',[['锁持有者','L']],[cell('H / 3','未就绪'),cell('M / 2','未就绪'),cell('L / 1','运行，持锁')],[2]),
 F('H想拿同一把锁，被阻塞','H: take(mutex);','H不能越过锁，它要等L完成。',[['等待关系','H 等 L']],[cell('H / 3','阻塞','等待锁'),cell('M / 2','就绪'),cell('L / 1','持锁','仍有临界区工作')],[0,2]),
 F('若无继承，M抢占L','// CPU=M, H等待, L就绪','M并不用锁，却阻止L释放锁，间接延长H等待。',[['CPU','M'],['问题','无关M延迟H']],[cell('H / 3','阻塞','等L释放'),cell('M / 2','运行','抢占L'),cell('L / 1','就绪持锁','不能尽快解锁')],[1]),
 F('有继承时，L临时提升','// L的有效优先级：1 → 3','锁持有者L被提高，先于M运行，完成解除H阻塞所需的工作。',[['CPU','L'],['L基础/有效优先级','1 / 3']],[cell('H / 3','阻塞','仍等待锁'),cell('M / 2','就绪','不能抢占临时3'),cell('L / 3','运行持锁','临时继承')],[2]),
 F('L释放单把锁，H继续','L: give(mutex);','本例L不持其他锁，恢复基础优先级；H取得锁继续。',[['CPU','H'],['L有效优先级','恢复1']],[cell('H / 3','运行','获得资源'),cell('M / 2','就绪'),cell('L / 1','就绪','已释放锁')],[0])
]);
flow('r-nvic-priority','Cortex-M3/M4示例：4有效位全作抢占位，未移位库级阈值=5。',[
 F('任务体系','Task: 0 < 1 < 2 < 3','任务数值越大越高；这里比的是任务Ready集合。',[['方向','数值大 → 任务优先级高']],[cell('任务1','较低'),cell('任务3','较高')],[1]),
 F('中断体系方向相反','NVIC: 0 最紧急，15 最不紧急','这些是中断优先级，不能与Task的数字混在一起。',[['方向','数值小 → 中断更紧急']],[cell('IRQ 0..4','更紧急','不允许调用内核API'),cell('IRQ 5..15','较低紧急度','允许区间内用FromISR')],[0]),
 F('检查阈值边界5','IRQ=5：在允许区间内','边界值5包含在允许区间，4不包含；同时还需满足ISR接口等条件。',[['IRQ4','禁止调内核API'],['IRQ5','可用FromISR'],['IRQ8','可用FromISR']],[cell('IRQ 4','禁止','高于阈值的紧急度'),cell('IRQ 5','允许范围','等于边界'),cell('IRQ 8','允许范围','紧急度更低')],[1]),
 F('再转换寄存器编码','5 << (8 - 4) = 0x50','实现位放在高位。CMSIS输入和FreeRTOS配置宏使用哪种值要按API/移植层核对，不重复移位。',[['未移位','5'],['已移位','0x50']],[cell('API逻辑值','5','按API约定输入'),cell('寄存器编码','0x50','左移4位')],[1])
]);
const a=[6,3,5,2,2,7];
expansionWalkthroughs['ds-valley']={kind:'valley',values:a,assumption:'示例[6,3,5,2,2,7]，下标从0开始，首尾不算。蓝线是数据；高亮点是本步检查对象。',frames:[
 F('先确认候选范围','for(i=1; i<n-1; ++i)','首尾缺一个邻居，只检查内部位置1到4。',[['严格计数','0'],['候选','1,2,3,4']],[],[],{highlight:[1,2,3,4]}),
 F('i=1：3比两边低','3 < 6 && 3 < 5','两个条件都真，所以这是严格波谷。',[['左/中/右','6 / 3 / 5'],['严格计数','1']],[],[],{highlight:[0,1,2]}),
 F('i=2：5是高点','5 < 3 // false','必须同时低于左右，左侧比较已经不满足。',[['严格计数','1']],[],[],{highlight:[1,2,3]}),
 F('i=3、4：相等阻止严格波谷','2 < 2 // false','3和4两个下标都与一个邻居相等，严格版不能计数。',[['严格计数','1'],['相等平台','[3,4]']],[],[],{highlight:[3,4]}),
 F('若题目改成平台版','5 > 2 && 7 > 2','把[3,4]合成一个平台，其外侧都更高，因此平台版额外计一次。',[['严格版总数','1'],['平台版总数','2']],[],[],{highlight:[2,3,4,5]})
]};
const b=[9,7,4,6,8,3,5];
const trace=[['初始','0','0','0',[0]],['9→7下降','1','0','0',[0,1]],['7→4下降','2','0','0',[0,1,2]],['4→6上升','2','1','4',[0,1,2,3]],['6→8上升','2','2','5',[0,1,2,3,4]],['8→3重新下降','1','0','5',[4,5]],['3→5上升','1','1','5',[4,5,6]]];
expansionWalkthroughs['ds-valley-longest']={kind:'valley',values:b,assumption:'严格先降后升，至少各一条边。down/up记录边数；best记录元素数。',frames:trace.map(([title,d,u,best,highlight],i)=>F(title,i===0?'down=up=best=0;':i===5?'down=1; up=0;':Number(u)>0?'best=max(best,down+up+1);':'++down;',i===5?'旧谷已结束；新谷从峰顶8开始，所以只保留8→3这一条下降边。':Number(u)>0?'已有下降和上升两种边，可形成谷。边数之和加1是元素数，和历史best比较。':'目前缺上升坡，不能用只有下降的长度更新best。',[['down',d],['up',u],['best',best]],[],[],{highlight}))};
